            System.Action<int> h = v => log.Add("H" + v);
            var t1 = ch.Subscribe(h);
            var t2 = ch.Subscribe(h);
            ch.Publish(1);
            string e = Expect(log, "H1 H1", "같은 델리게이트를 두 번 구독하면 두 번 호출");
