            if (e != null) return e;
            return ch.SubscriberCount == 2 ? null : "SubscriberCount 기대 2, 결과 " + ch.SubscriberCount;
        });

        Run("subscribe-during-publish", () =>
        {
            var ch = new EventChannel<int>();
            var log = new System.Collections.Generic.List<string>();
            ch.Subscribe(v => { log.Add("A" + v); if (v == 1) ch.Subscribe(w => log.Add("N" + w)); });
            ch.Subscribe(v => log.Add("B" + v));
            ch.Publish(1);
            string e = Expect(log, "A1 B1", "Publish 도중 추가된 구독은 그 Publish 에서 호출되면 안 됨");
