using System;
using System.Collections.Generic;

public enum CharState { Idle, Move, Attack, Stunned, Dead }

public interface IState
{
    void Enter(CharacterFsm fsm);
    void Update(CharacterFsm fsm, float dt);
    void Exit(CharacterFsm fsm);
}

public sealed class CharacterFsm
{
    private readonly Dictionary<CharState, IState> _states = new Dictionary<CharState, IState>();
    private readonly HashSet<(CharState, CharState)> _allowed = new HashSet<(CharState, CharState)>();
    private readonly Queue<CharState> _pending = new Queue<CharState>();

    private bool _started;
    private bool _inHook;            // Enter / Exit / Update 중 하나가 실행 중인가
    private CharState _current;
    private CharState _logical;      // 수락된 요청이 모두 적용된 뒤의 상태

    public CharState Current
    {
        get { EnsureStarted(); return _current; }
    }

    public void AddState(CharState id, IState state)
    {
        if (state == null) throw new ArgumentNullException(nameof(state));
        if (_states.ContainsKey(id)) throw new ArgumentException("이미 등록된 상태: " + id);
        _states.Add(id, state);
    }

    public void AllowTransition(CharState from, CharState to)
    {
        _allowed.Add((from, to));
    }

    public void Start(CharState initial)
    {
        if (_started) throw new InvalidOperationException("이미 시작됨");
        if (!_states.ContainsKey(initial)) throw new InvalidOperationException("등록되지 않은 상태: " + initial);
        _started = true;
        _current = initial;
        _logical = initial;
        _inHook = true;
        try { _states[initial].Enter(this); }
        finally { _inHook = false; }
        Drain();                     // 초기 Enter 안에서 요청된 전이
    }

    public bool RequestTransition(CharState to)
    {
        EnsureStarted();
        // 검증 기준은 "이 요청이 적용될 시점의 상태"다.
        if (!_states.ContainsKey(to) || !_allowed.Contains((_logical, to))) return false;
        _logical = to;
        _pending.Enqueue(to);
        if (!_inHook) Drain();       // 훅 밖이면 지금 바로, 훅 안이면 그 훅을 부른 쪽이 처리한다
        return true;
    }

    public void Update(float dt)
    {
        EnsureStarted();
        if (_inHook) throw new InvalidOperationException("훅 안에서 Update 를 다시 호출할 수 없음");
        _inHook = true;
        try { _states[_current].Update(this, dt); }
        finally { _inHook = false; }
        Drain();
    }

    // 대기 중인 전이를 요청 순서대로 하나씩 끝까지 적용한다.
    // 훅 안에서 새 요청이 들어오면 큐 뒤에 붙고, 이 루프가 이어서 처리한다(재귀 없음).
    private void Drain()
    {
        _inHook = true;
        try
        {
            while (_pending.Count > 0)
            {
                CharState to = _pending.Dequeue();
                _states[_current].Exit(this);
                _current = to;
                _states[to].Enter(this);
            }
        }
        finally { _inHook = false; }
    }

    private void EnsureStarted()
    {
        if (!_started) throw new InvalidOperationException("Start 를 먼저 호출해야 함");
    }
}

