public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    sealed class Cmd : ICommand
    {
        readonly string _id; readonly System.Action<GameState> _run;
        public Cmd(string id, System.Action<GameState> run) { _id = id; _run = run; }
        public string Id { get { return _id; } }
        public void Execute(GameState s) { _run(s); }
    }

    static readonly string[] Ids = { "up", "right", "attack", "dash", "rest" };

    static void Apply(string id, GameState s)
    {
        switch (id)
        {
            case "up": s.Y += 1; break;
            case "right": s.X += 1; break;
            case "attack":
                if (s.Cooldown == 0 && s.Stamina >= 20) { s.Stamina -= 20; s.Cooldown = 3; s.EnemyHp -= 10 + s.NextRandom(6); }
                break;
            case "dash":
                if (s.Stamina >= 30) { s.Stamina -= 30; s.X += 3; }
                break;
            case "rest": s.Stamina = System.Math.Min(100, s.Stamina + 5); break;
        }
    }

    static CommandInput NewInput()
    {
        var input = new CommandInput();
        foreach (string id in Ids) { string captured = id; input.Register(new Cmd(captured, s => Apply(captured, s))); }
        return input;
    }

    static string Rec(System.Collections.Generic.IReadOnlyList<RecordedCommand> r)
    {
        var parts = new System.Collections.Generic.List<string>();
        for (int i = 0; i < r.Count; i++) parts.Add(r[i].Frame + ":" + r[i].CommandId);
        return string.Join(" ", parts);
    }

    public static void Main()
    {
        Run("press-buffer-execute", () =>
        {
