using System;
using System.Collections.Generic;

// ----- 아래 타입들은 완성되어 있습니다. 수정하지 마세요. -----

public sealed class Unit
{
    private readonly List<int[]> _dots = new List<int[]>();   // { 틱당 데미지, 남은 틱 }

    public string Name { get; }
    public int MaxHp { get; }
    public int Hp { get; private set; }
    public bool IsDead { get { return Hp == 0; } }
    public int DotCount { get { return _dots.Count; } }

    public Unit(string name, int maxHp) { Name = name; MaxHp = maxHp; Hp = maxHp; }

    public void TakeDamage(int amount)
    {
        if (amount <= 0 || IsDead) return;
        Hp = Math.Max(0, Hp - amount);
    }

    // 죽은 유닛은 회복되지 않는다.
    public void Heal(int amount)
    {
        if (amount <= 0 || IsDead) return;
        Hp = Math.Min(MaxHp, Hp + amount);
    }

    public void AddDot(int damagePerTick, int ticks)
    {
        if (damagePerTick <= 0 || ticks <= 0 || IsDead) return;
        _dots.Add(new[] { damagePerTick, ticks });
    }

    // 턴(틱) 하나 진행: 걸려 있는 지속 피해를 한 번씩 적용한다.
    public void Tick()
    {
        for (int i = _dots.Count - 1; i >= 0; i--)
        {
            TakeDamage(_dots[i][0]);
            if (--_dots[i][1] <= 0) _dots.RemoveAt(i);
        }
        if (IsDead) _dots.Clear();
    }
}

// 스킬 데이터 한 줄: "어떤 효과를, 얼마의 세기로, 몇 틱 동안"
public readonly struct EffectSpec
{
    public readonly string EffectId;
    public readonly int Power;
    public readonly int Duration;
    public EffectSpec(string effectId, int power, int duration) { EffectId = effectId; Power = power; Duration = duration; }
}

public sealed class SkillData
{
    public readonly string Name;
    public readonly EffectSpec[] Effects;
    public SkillData(string name, params EffectSpec[] effects) { Name = name; Effects = effects; }
}

// 효과 하나의 동작(전략). 상태를 갖지 않고, 수치는 spec 에서 읽는다.
public interface ISkillEffect
{
    void Apply(Unit caster, Unit target, EffectSpec spec);
}

public sealed class DamageEffect : ISkillEffect
{
    public void Apply(Unit caster, Unit target, EffectSpec spec) { target.TakeDamage(spec.Power); }
}

public sealed class HealEffect : ISkillEffect
{
    public void Apply(Unit caster, Unit target, EffectSpec spec) { target.Heal(spec.Power); }
}

public sealed class DotEffect : ISkillEffect
{
    public void Apply(Unit caster, Unit target, EffectSpec spec) { target.AddDot(spec.Power, spec.Duration); }
}

public sealed class EffectRegistry
{
    // 인스턴스 필드다. static 으로 두면 테스트와 모드(PvE / PvP)가 서로의 등록을 오염시킨다.
    private readonly Dictionary<string, ISkillEffect> _effects = new Dictionary<string, ISkillEffect>(StringComparer.Ordinal);

    public void Register(string id, ISkillEffect effect)
    {
        if (string.IsNullOrEmpty(id)) throw new ArgumentException("효과 id 가 비어 있음", nameof(id));
        if (effect == null) throw new ArgumentNullException(nameof(effect));
        if (_effects.ContainsKey(id)) throw new ArgumentException("이미 등록된 효과 id: " + id, nameof(id));
        _effects.Add(id, effect);
    }

    public bool TryGet(string id, out ISkillEffect effect)
    {
        if (id == null) { effect = null; return false; }
        return _effects.TryGetValue(id, out effect);
    }

    public static EffectRegistry CreateDefault()
    {
        EffectRegistry registry = new EffectRegistry();
        registry.Register("damage", new DamageEffect());
        registry.Register("heal", new HealEffect());
        registry.Register("dot", new DotEffect());
        return registry;
    }
}

public sealed class SkillCaster
{
    private readonly EffectRegistry _registry;

    public SkillCaster(EffectRegistry registry)
    {
        if (registry == null) throw new ArgumentNullException(nameof(registry));
        _registry = registry;       // 복사하지 않고 참조만 든다: 나중에 등록된 효과도 보인다
    }

    public bool Cast(SkillData skill, Unit caster, Unit target)
    {
        if (skill == null) throw new ArgumentNullException(nameof(skill));
        EffectSpec[] specs = skill.Effects;
        ISkillEffect effect;

        // 1) 검증: 하나라도 모르는 id 가 있으면 아무것도 적용하지 않는다.
        for (int i = 0; i < specs.Length; i++)
        {
            if (!_registry.TryGet(specs[i].EffectId, out effect)) return false;
        }

        // 2) 적용: 데이터 순서 그대로. 시전자는 효과의 종류를 전혀 모른다.
        for (int i = 0; i < specs.Length; i++)
        {
            _registry.TryGet(specs[i].EffectId, out effect);
            effect.Apply(caster, target, specs[i]);
        }
        return true;
    }
}

