public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 테스트 쪽에서 추가하는 효과: 입힌 피해의 절반만큼 시전자를 회복
    sealed class Lifesteal : ISkillEffect
    {
        public void Apply(Unit caster, Unit target, EffectSpec spec)
        {
            int before = target.Hp;
            target.TakeDamage(spec.Power);
            caster.Heal((before - target.Hp) / 2);
        }
    }

    sealed class Counting : ISkillEffect
    {
        public int Calls;
        public void Apply(Unit caster, Unit target, EffectSpec spec) { Calls++; }
    }

    static EffectSpec E(string id, int power, int duration = 0) { return new EffectSpec(id, power, duration); }

    static string St(Unit u) { return u.Name + " " + u.Hp + "/" + u.MaxHp + " dot" + u.DotCount; }

    static bool ThrowsArg(System.Action a)
    {
        try { a(); } catch (System.ArgumentException) { return true; } catch (System.Exception) { return false; }
        return false;
    }

    // 참조 구현: 일부러 switch 로 쓴 "정답 계산기"
    static bool RefCast(SkillData skill, Unit caster, Unit target, bool lifestealKnown)
    {
        foreach (EffectSpec s in skill.Effects)
        {
            bool known = s.EffectId == "damage" || s.EffectId == "heal" || s.EffectId == "dot" || (lifestealKnown && s.EffectId == "lifesteal");
            if (!known) return false;
        }
        foreach (EffectSpec s in skill.Effects)
        {
            switch (s.EffectId)
            {
                case "damage": target.TakeDamage(s.Power); break;
                case "heal": target.Heal(s.Power); break;
                case "dot": target.AddDot(s.Power, s.Duration); break;
                case "lifesteal": new Lifesteal().Apply(caster, target, s); break;
            }
        }
        return true;
    }

    public static void Main()
    {
        Run("builtin-effects", () =>
        {
            var caster = new SkillCaster(EffectRegistry.CreateDefault());
            var mage = new Unit("mage", 80); var orc = new Unit("orc", 100);
            if (!caster.Cast(new SkillData("fireball", E("damage", 30), E("dot", 5, 3)), mage, orc)) return "기본 효과만 쓴 스킬의 Cast 가 false";
            if (St(orc) != "orc 70/100 dot1") return "fireball(damage 30 + dot 5x3) 직후 기대 orc 70/100 dot1, 결과 " + St(orc);
            orc.Tick(); orc.Tick(); orc.Tick(); orc.Tick();
            if (St(orc) != "orc 55/100 dot0") return "4틱 뒤 기대 orc 55/100 dot0, 결과 " + St(orc);
            caster.Cast(new SkillData("mend", E("heal", 20)), mage, orc);
            if (St(orc) != "orc 75/100 dot0") return "heal 20 뒤 기대 orc 75/100, 결과 " + St(orc);
            if (!caster.Cast(new SkillData("empty"), mage, orc) || St(orc) != "orc 75/100 dot0") return "효과가 없는 스킬은 true 를 반환하고 아무것도 바꾸지 않아야 함";
            return St(mage) == "mage 80/80 dot0" ? null : "시전자 상태가 바뀜: " + St(mage);
        });

        Run("data-order", () =>
        {
            var caster = new SkillCaster(EffectRegistry.CreateDefault());
            var a = new Unit("a", 100); var t1 = new Unit("t1", 40); var t2 = new Unit("t2", 40);
            t1.TakeDamage(10); t2.TakeDamage(10);
            caster.Cast(new SkillData("smite-then-mend", E("damage", 30), E("heal", 15)), a, t1);
            caster.Cast(new SkillData("mend-then-smite", E("heal", 15), E("damage", 30)), a, t2);
            if (t1.Hp != 0) return "HP 30 에 damage 30 -> heal 15 순서: 죽은 뒤에는 회복되지 않으므로 기대 0, 결과 " + t1.Hp;
            if (t2.Hp != 10) return "HP 30 에 heal 15 -> damage 30 순서: 기대 10, 결과 " + t2.Hp;
            return null;
        });

        Run("unknown-id-atomic", () =>
        {
            var caster = new SkillCaster(EffectRegistry.CreateDefault());
            var a = new Unit("a", 100); var t = new Unit("t", 100);
            bool ok = caster.Cast(new SkillData("broken", E("damage", 30), E("dot", 5, 3), E("teleport", 1)), a, t);
            if (ok) return "등록되지 않은 id(teleport)가 있는데 Cast 가 true";
            if (St(t) != "t 100/100 dot0") return "실패한 Cast 가 앞쪽 효과를 이미 적용함: " + St(t);
            if (caster.Cast(new SkillData("case", E("Damage", 30)), a, t) || t.Hp != 100) return "id 는 대소문자를 구분해야 함 (\"Damage\" 는 미등록)";
            if (caster.Cast(new SkillData("null-id", E(null, 30)), a, t) || t.Hp != 100) return "EffectId 가 null 인 스펙은 미등록으로 처리해 false 여야 함";
            return null;
        });

        Run("custom-effect-from-test", () =>
        {
            var reg = EffectRegistry.CreateDefault();
            reg.Register("lifesteal", new Lifesteal());
            var caster = new SkillCaster(reg);
            var vamp = new Unit("vamp", 100); var t = new Unit("t", 50);
            vamp.TakeDamage(60);
            if (!caster.Cast(new SkillData("drain", E("lifesteal", 40), E("damage", 5)), vamp, t)) return "테스트가 등록한 효과 id 로 Cast 했는데 false";
            if (St(t) != "t 5/50 dot0" || vamp.Hp != 60) return "drain(lifesteal 40 + damage 5) 뒤 기대 t 5/50, vamp 60, 결과 " + St(t) + ", vamp " + vamp.Hp;
            return null;
        });

        Run("register-after-caster", () =>
        {
            var reg = EffectRegistry.CreateDefault();
            var caster = new SkillCaster(reg);
            var a = new Unit("a", 100); var t = new Unit("t", 100);
            a.TakeDamage(50);
            var drain = new SkillData("drain", E("lifesteal", 20));
            if (caster.Cast(drain, a, t)) return "아직 등록되지 않은 효과인데 Cast 가 true";
            reg.Register("lifesteal", new Lifesteal());
            if (!caster.Cast(drain, a, t)) return "SkillCaster 를 만든 뒤에 등록한 효과가 보이지 않음 (생성 시점에 목록을 복사했는가?)";
            return t.Hp == 80 && a.Hp == 60 ? null : "기대 t 80, a 60, 결과 t " + t.Hp + ", a " + a.Hp;
        });

        Run("register-validation", () =>
        {
            var reg = EffectRegistry.CreateDefault();
            if (!ThrowsArg(() => reg.Register("damage", new Lifesteal()))) return "이미 있는 id 를 다시 Register 해도 ArgumentException 이 없음";
            if (!ThrowsArg(() => reg.Register("x", null))) return "effect 가 null 인데 ArgumentException(파생 포함)이 없음";
            if (!ThrowsArg(() => reg.Register(null, new Lifesteal()))) return "id 가 null 인데 ArgumentException(파생 포함)이 없음";
            if (!ThrowsArg(() => reg.Register("", new Lifesteal()))) return "id 가 빈 문자열인데 ArgumentException 이 없음";
            ISkillEffect found;
            if (!reg.TryGet("heal", out found) || found == null) return "TryGet(\"heal\") 이 기본 효과를 찾지 못함";
            if (reg.TryGet("x", out found) || found != null) return "실패한 Register 가 등록을 남김 (TryGet(\"x\") 는 false, effect 는 null 이어야 함)";
            var t = new Unit("t", 100);
            new SkillCaster(reg).Cast(new SkillData("hit", E("damage", 10)), t, t);
            return t.Hp == 90 ? null : "중복 Register 시도 뒤 기존 damage 효과가 바뀜 (HP " + t.Hp + ")";
        });

        Run("registries-independent", () =>
        {
            var empty = new EffectRegistry();
            ISkillEffect found;
            if (empty.TryGet("damage", out found)) return "new EffectRegistry() 는 비어 있어야 함 (기본 효과는 CreateDefault 에서만)";
            var t = new Unit("t", 100);
            if (new SkillCaster(empty).Cast(new SkillData("hit", E("damage", 10)), t, t) || t.Hp != 100) return "빈 레지스트리로 damage 가 적용됨";
            var counting = new Counting();
            empty.Register("damage", counting);
            new SkillCaster(empty).Cast(new SkillData("hit", E("damage", 10), E("damage", 10)), t, t);
            if (counting.Calls != 2 || t.Hp != 100) return "레지스트리에 등록된 객체가 아닌 다른 경로로 damage 가 처리됨 (호출 " + counting.Calls + "회, HP " + t.Hp + ")";
            var r1 = EffectRegistry.CreateDefault(); var r2 = EffectRegistry.CreateDefault();
            r1.Register("lifesteal", new Lifesteal());
            if (r2.TryGet("lifesteal", out found)) return "한 레지스트리에 등록한 효과가 다른 레지스트리에도 보임 (static 저장소를 공유하고 있음)";
            return null;
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(555);
            string[] ids = { "damage", "heal", "dot", "lifesteal", "teleport" };
            for (int round = 0; round < 300; round++)
            {
                bool withLifesteal = rng.Next(2) == 0;
                var reg = EffectRegistry.CreateDefault();
                if (withLifesteal) reg.Register("lifesteal", new Lifesteal());
                var caster = new SkillCaster(reg);
                var a = new Unit("a", 120); var t = new Unit("t", 90);
                var ra = new Unit("a", 120); var rt = new Unit("t", 90);
                for (int step = 0; step < 12; step++)
                {
                    int n = rng.Next(0, 4);
                    var specs = new EffectSpec[n];
                    for (int i = 0; i < n; i++)
                    {
                        int pick = rng.Next(100);
                        string id = pick < 30 ? ids[0] : pick < 50 ? ids[1] : pick < 70 ? ids[2] : pick < 93 ? ids[3] : ids[4];
                        specs[i] = E(id, rng.Next(0, 35), rng.Next(0, 4));
                    }
                    var skill = new SkillData("s", specs);
                    bool swap = rng.Next(4) == 0;
                    bool got = swap ? caster.Cast(skill, t, a) : caster.Cast(skill, a, t);
                    bool exp = swap ? RefCast(skill, rt, ra, withLifesteal) : RefCast(skill, ra, rt, withLifesteal);
                    if (rng.Next(3) == 0) { a.Tick(); t.Tick(); ra.Tick(); rt.Tick(); }
                    if (got != exp || St(a) != St(ra) || St(t) != St(rt))
                    {
                        var names = new System.Collections.Generic.List<string>();
                        foreach (EffectSpec s in specs) names.Add(s.EffectId + "(" + s.Power + "," + s.Duration + ")");
                        return "라운드 " + round + ", 스킬 [" + string.Join(" ", names) + "]" + (withLifesteal ? " (lifesteal 등록됨)" : " (lifesteal 미등록)") +
                            ": 기대 " + exp + " / " + St(ra) + " / " + St(rt) + ", 결과 " + got + " / " + St(a) + " / " + St(t);
                    }
                }
            }
            return null;
        });
    }
}
